{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(field, text, least) {
  if (!COUNT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function run(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let allowed = 0
  let denied = 0
  let started = false
  let last = null

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const n = i + 1
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        const want = d === 'bucket' ? 5 : d === 'window' ? 4 : 3
        const shape = d === 'bucket' ? 'bucket <name> <capacity> <refill> <per>'
          : d === 'window' ? 'window <name> <limit> <span>' : 'route <prefix> <policy>...'
        if (d === 'route' ? f.length < want : f.length !== want) throw new Fail(`expected ${shape}`)
        if (started) throw new Fail('declarations must come before the first event')
        if (d === 'route') {
          if (!WORD.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
          if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
          const list = []
          for (const p of f.slice(2)) {
            if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
            list.push(policies.get(p))
          }
          routes.set(f[1], list)
        } else {
          if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
          let p
          if (d === 'bucket') {
            const capacity = count('capacity', f[2], 1)
            const refill = count('refill', f[3], 0)
            const per = count('per', f[4], 1)
            p = { name: f[1], kind: 'bucket', capacity, refill, per, state: new Map() }
          } else {
            const limit = count('limit', f[2], 0)
            const span = count('span', f[3], 1)
            p = { name: f[1], kind: 'window', limit, span, state: new Map() }
          }
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          policies.set(f[1], p)
        }
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count('tick', f[1], 0)
        const key = f[2]
        if (!WORD.test(key)) throw new Fail(`invalid key ${key}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        started = true
        let best = null
        for (const [prefix, list] of routes) {
          if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
        }
        let refusal = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            let s = p.state.get(key)
            if (p.kind === 'bucket') {
              // units are tokens * per, so fractions stay exact
              if (!s) s = { units: p.capacity * p.per, at: tick }
              else {
                s.units += p.refill * (tick - s.at)
                s.at = tick
                if (s.units > p.capacity * p.per) s.units = p.capacity * p.per
              }
            } else {
              if (!s) s = { ticks: [] }
              s.ticks = s.ticks.filter((t) => t > tick - p.span)
            }
            p.state.set(key, s)
            return s
          })
          for (let j = 0; j < list.length && !refusal; j++) {
            const p = list[j]
            const ok = p.kind === 'bucket' ? sts[j].units >= p.per : BigInt(sts[j].ticks.length) < p.limit
            if (!ok) refusal = p.name
          }
          if (!refusal) {
            list.forEach((p, j) => {
              if (p.kind === 'bucket') sts[j].units -= p.per
              else sts[j].ticks.push(tick)
            })
          }
        }
        const st = stats.get(key) || { a: 0, d: 0 }
        stats.set(key, st)
        if (refusal) { st.d++; denied++ } else { st.a++; allowed++ }
        out.push(`${tick} ${key} ${refusal ? `deny ${refusal}` : 'allow'}`)
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${n}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'replay') return out
  const res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${allowed} denied=${denied}`)
  return res
}

try {
  const lines = run(readFileSync(0, 'utf8'))
  process.stdout.write(lines.map((l) => l + '\n').join(''))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
}
"}

