#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`, 2)
      if (!NAME.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`, 2)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`, 2)
      tasks.set(w[1], { name: w[1], cost: Number(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`, 2)
    }
  })
  for (const names of depLines) {
    for (const nm of names) if (!tasks.has(nm)) throw new Fail(`error: unknown task ${nm}`, 2)
  }
  for (const [first, ...rest] of depLines) for (const d of rest) tasks.get(first).deps.add(d)
  return tasks
}

function checkCycle(tasks, order) {
  const state = new Map()
  const stack = []
  const visit = (nm) => {
    state.set(nm, 1)
    stack.push(nm)
    for (const d of [...tasks.get(nm).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(nm, 2)
  }
  for (const nm of order) if (!state.get(nm)) visit(nm)
}

function schedule(tasks, order) {
  const info = new Map()
  const calc = (nm) => {
    if (info.has(nm)) return info.get(nm)
    const t = tasks.get(nm)
    let start = 0
    let depth = 0
    for (const d of t.deps) {
      const x = calc(d)
      start = Math.max(start, x.finish)
      depth = Math.max(depth, x.depth + 1)
    }
    const r = { start, finish: start + t.cost, depth }
    info.set(nm, r)
    return r
  }
  for (const nm of order) calc(nm)
  return info
}

function pack(tasks, order, workers) {
  const dependents = new Map(order.map((n) => [n, []]))
  for (const t of tasks.values()) for (const d of t.deps) dependents.get(d).push(t.name)
  const prio = new Map()
  const pr = (nm) => {
    if (prio.has(nm)) return prio.get(nm)
    let best = 0
    for (const x of dependents.get(nm)) best = Math.max(best, pr(x))
    const v = best + tasks.get(nm).cost
    prio.set(nm, v)
    return v
  }
  for (const nm of order) pr(nm)
  const finish = new Map()
  const freeAt = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0
  let makespan = 0
  while (finish.size < order.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const nm of order) {
        if (finish.has(nm)) continue
        let ok = true
        for (const d of tasks.get(nm).deps) {
          if (!finish.has(d) || finish.get(d) > t) { ok = false; break }
        }
        if (!ok) continue
        if (pick === null || prio.get(nm) > prio.get(pick)) pick = nm
      }
      if (pick === null) break
      const end = t + tasks.get(pick).cost
      finish.set(pick, end)
      freeAt[w] = end
      ran[w].push(`${pick}@${t}-${end}`)
      makespan = Math.max(makespan, end)
    }
    if (finish.size >= order.length) break
    let next = Infinity
    for (const f of freeAt) if (f > t && f < next) next = f
    for (const f of finish.values()) if (f > t && f < next) next = f
    t = next
  }
  let out = ''
  ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  return out + `makespan ${makespan}\n`
}

function main(argv) {
  const mode = argv[0]
  let workers = 0
  if (mode === 'pack') {
    if (argv.length !== 2) throw new Fail('error: usage: cli.js waves|explain|pack <workers>', 2)
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new Fail('error: workers must be a positive integer', 2)
    workers = Number(argv[1])
  } else if (!((mode === 'waves' || mode === 'explain') && argv.length === 1)) {
    throw new Fail('error: usage: cli.js waves|explain|pack <workers>', 2)
  }
  const tasks = parse(readFileSync(0, 'utf8'))
  const order = [...tasks.keys()].sort(cmp)
  checkCycle(tasks, order)
  if (mode === 'pack') return pack(tasks, order, workers)
  const info = schedule(tasks, order)
  let total = 0
  for (const v of info.values()) total = Math.max(total, v.finish)
  let out = ''
  if (mode === 'waves') {
    const waves = []
    for (const nm of order) (waves[info.get(nm).depth] ||= []).push(nm)
    waves.forEach((w, k) => { out += `wave ${k}: ${w.join(' ')}\n` })
  } else {
    for (const nm of order) {
      const v = info.get(nm)
      out += `${nm} start=${v.start} finish=${v.finish} depth=${v.depth}\n`
    }
  }
  return out + `total ${total}\n`
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(e.code)
}
