    if (!ok(cs[j])) return j
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      let depth = 1
      let j = i + 2
      while (j < n && depth > 0) {
        if (cs[j] === '/' && cs[j + 1] === '*') { depth++; j += 2 }
        else if (cs[j] === '*' && cs[j + 1] === '/') { depth--; j += 2 }
        else j++
      }
      if (depth > 0) fail(i, 'unterminated block comment')
      i = j
      continue
    }
    const start = i
    const push = (kind, body) => tokens.push({ line: lines[start], col: cols[start], kind, body })
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      push('rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
