import { readFileSync } from 'node:fs'

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^/?#]*):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuth(a) {
  if (a === undefined) return {}
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function check(u, n) {
  const a = splitAuth(u.authority)
  const parts = [['path', u.path], ['userinfo', a.userinfo], ['host', a.host], ['query', u.query], ['fragment', u.fragment]]
  for (const [name, v] of parts) {
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
      throw new Fail(`error: line ${n}: the ${name} has a truncated percent-encoding`)
    }
  }
}

function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      const i = out.lastIndexOf('/')
      out = i >= 0 ? out.slice(0, i) : ''
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function normalize(u) {
  const scheme = u.scheme === undefined ? undefined : lower(u.scheme)
  let path = removeDots(pct(u.path))
  const query = pct(u.query)
  const fragment = pct(u.fragment)
  let auth
  if (u.authority !== undefined) {
    const a = splitAuth(u.authority)
    let port = a.port
    if (port === '' || (scheme !== undefined && DEFAULTS[scheme] === port)) port = undefined
    auth = (a.userinfo !== undefined ? pct(a.userinfo) + '@' : '') + lower(pct(a.host)) + (port !== undefined ? ':' + port : '')
    if (path === '') path = '/'
  }
  let r = ''
  if (scheme !== undefined) r += scheme + ':'
  if (auth !== undefined) r += '//' + auth
  r += path
  if (query !== undefined) r += '?' + query
  if (fragment !== undefined) r += '#' + fragment
  return r
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    t.query = ref.query
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i >= 0 ? base.path.slice(0, i + 1) + ref.path : ref.path
      }
      t.path = removeDots(merged)
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new Fail('error: usage: cli.js normalize|resolve')
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((line, idx) => {
    const n = idx + 1
    if (args[0] === 'normalize') {
      const u = parse(line)
      check(u, n)
      out.push(normalize(u))
      return
    }
    const sp = line.indexOf(' ')
    if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
    const base = parse(line.slice(0, sp))
    const ref = parse(line.slice(sp + 1))
    if (base.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
    check(base, n)
    check(ref, n)
    out.push(normalize(resolve(base, ref)))
  })
  process.stdout.write(out.map((l) => l + '\n').join(''))
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
