import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const WORD = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`line ${i + 1}: ${m}`) }
    const num = (v, name, least) => {
      if (!UINT.test(v) || BigInt(v) < BigInt(least)) fail(`${name} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') fail(`unknown directive ${d}`)
    if (d !== 'event' && started) fail('declarations must come before the first event')
    if (d === 'bucket') {
      if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!WORD.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const capacity = num(f[2], 'capacity', 1)
      const refill = num(f[3], 'refill', 0)
      const per = num(f[4], 'per', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], type: 'bucket', capacity, refill, per })
    } else if (d === 'window') {
      if (f.length !== 4) fail('expected window <name> <limit> <span>')
      if (!WORD.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const limit = num(f[2], 'limit', 0)
      const span = num(f[3], 'span', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], type: 'window', limit, span })
    } else if (d === 'route') {
      if (f.length < 3) fail('expected route <prefix> <policy>...')
      if (!WORD.test(f[1])) fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
      const list = f.slice(2).map((n) => {
        if (!policies.has(n)) fail(`unknown policy ${n}`)
        return policies.get(n)
      })
      routes.set(f[1], list)
    } else {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = num(f[1], 'tick', 0)
      if (!WORD.test(f[2])) fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      started = true
      events.push([tick, f[2]])
    }
  })
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map() // "policy\0key" -> state
  const stateFor = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.type === 'bucket' ? { tokens: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const out = []
  const counts = new Map()
  let ta = 0, td = 0
  for (const [tick, key] of events) {
    let best = null
    for (const pre of routes.keys()) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denier = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const s = stateFor(p, key, tick)
        if (p.type === 'bucket') {
          const cap = p.capacity * p.per
          s.tokens += p.refill * (tick - s.last)
          if (s.tokens > cap) s.tokens = cap
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const p = list[i], s = sts[i]
        const ok = p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
      if (denier === null) {
        list.forEach((p, i) => {
          if (p.type === 'bucket') sts[i].tokens -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const c = counts.get(key) || [0, 0]
    if (denier === null) { c[0]++; ta++ } else { c[1]++; td++ }
    counts.set(key, c)
    out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${counts.get(k)[0]} denied=${counts.get(k)[1]}\n`).join('') +
    `total allowed=${ta} denied=${td}\n`
}

let result
try {
  result = run(parse(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
