{"file_path":"src/merge.js","content":"function changes(base, side) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const result = []
  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) result.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n
  j = m
  flush()
  return result
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const docs = [mine, theirs]
  const out = []
  let pos = 0
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) out.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    if (group.length === 1) {
      const c = group[0]
      out.push({ kind: c.side ? 'theirs' : 'mine', lines: docs[c.side].slice(c.ss, c.se) })
      continue
    }
    const baseLines = base.slice(rs, re)
    const sideLines = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const minB = Math.min(...cs.map(c => c.bs))
      const maxE = Math.max(...cs.map(c => c.be))
      const start = cs[0].ss - (minB - rs)
      const end = cs[cs.length - 1].se + (re - maxE)
      return docs[s].slice(start, end)
    })
    const [m, t] = sideLines
    if (same(m, t)) out.push({ kind: 'both', lines: m })
    else if (same(m, baseLines)) out.push({ kind: 'theirs', lines: t })
    else if (same(t, baseLines)) out.push({ kind: 'mine', lines: m })
    else out.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
  }
  if (pos < base.length) out.push({ kind: 'stable', lines: base.slice(pos) })
  return out
}
"}

