    if (group.length === 1) {
      const c = group[0]
      out.push({ kind: c.side ? 'theirs' : 'mine', lines: docs[c.side].slice(c.ss, c.se) })
      continue
    }
    const baseLines = base.slice(rs, re)
    const sideLines = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const minB = Math.min(...cs.map(c => c.bs))
      const maxE = Math.max(...cs.map(c => c.be))
      const start = cs[0].ss - (minB - rs)
      const end = cs[cs.length - 1].se + (re - maxE)
      return docs[s].slice(start, end)
    })
    const [m, t] = sideLines
    if (same(m, t)) out.push({ kind: 'both', lines: m })
    else if (same(m, baseLines)) out.push({ kind: 'theirs', lines: t })
    else if (same(t, baseLines)) out.push({ kind: 'mine', lines: m })
    else out.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
  }
  if (pos < base.length) out.push({ kind: 'stable', lines: base.slice(pos) })
  return out
}
