/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { merge } from './merge.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) {
  fail('usage: cli.js merge|merge2|regions')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const line of lines) {
  if (line === '%%%') docs.push([])
  else docs[docs.length - 1].push(line)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')

const regions = merge(docs[0], docs[1], docs[2])
const out = []
let conflict = false
for (const r of regions) {
  if (mode === 'regions') {
    if (r.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`)
    } else out.push(`${r.kind} ${r.lines.length}`)
  } else if (r.kind === 'conflict') {
    conflict = true
    out.push('<<<<<<< mine', ...r.mine)
    if (mode === 'merge') out.push('||||||| base', ...r.base)
    out.push('=======', ...r.theirs, '>>>>>>> theirs')
  } else out.push(...r.lines)
}
process.stdout.write(out.map(l => `${l}\n`).join(''))
process.exit(conflict ? 1 : 0)
"}

