export function findCycle(g) {
  const state = new Map()
  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of g.deps.get(n)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const r = visit(d)
        if (r) return r
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of g.names) {
    if (!state.get(n)) {
      const r = visit(n)
      if (r) return r
    }
  }
  return null
}

/** Topological order (dependencies first), names ascending among ties of DFS. */
function order(g) {
  const seen = new Set()
  const out = []
  const visit = (n) => {
    seen.add(n)
    for (const d of g.deps.get(n)) if (!seen.has(d)) visit(d)
    out.push(n)
  }
  for (const n of g.names) if (!seen.has(n)) visit(n)
  return out
}

export function timing(g) {
  const info = new Map()
  let total = 0n
  for (const n of order(g)) {
    let start = 0n
    let depth = 0
    for (const d of g.deps.get(n)) {
      const i = info.get(d)
      if (i.finish > start) start = i.finish
      if (i.depth + 1 > depth) depth = i.depth + 1
    }
    const finish = start + g.cost.get(n)
    info.set(n, { start, finish, depth })
    if (finish > total) total = finish
  }
  return { info, total }
}

export function pack(g, workers) {
  const ord = order(g)
  const users = new Map(g.names.map((n) => [n, []]))
  for (const n of g.names) for (const d of g.deps.get(n)) users.get(d).push(n)
  const prio = new Map()
  for (let i = ord.length - 1; i >= 0; i--) {
    const n = ord[i]
    let best = 0n
    for (const u of users.get(n)) if (prio.get(u) > best) best = prio.get(u)
    prio.set(n, best + g.cost.get(n))
  }
  const finish = new Map()
  const freeAt = new Array(workers).fill(0n)
  const lines = Array.from({ length: workers }, () => [])
  let pending = g.names.slice()
  let t = 0n
  let makespan = 0n
  while (pending.length) {
    for (;;) {
      let w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const n of pending) {
        if (!g.deps.get(n).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (best === null || prio.get(n) > prio.get(best)) best = n
      }
      if (best === null) break
      const f = t + g.cost.get(best)
      finish.set(best, f)
      freeAt[w] = f
      lines[w].push({ name: best, start: t, finish: f })
      if (f > makespan) makespan = f
      pending = pending.filter((n) => n !== best)
    }
    if (!pending.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return { lines, makespan }
}
"}

