const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'values' && mode[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'err', v: code })
const num = (v) => ({ t: 'num', v })
const bool = (v) => ({ t: 'bool', v })
const text = (v) => ({ t: 'text', v })

// ---- addresses ----
function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1
    ? L.charCodeAt(0) - 64
    : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: col + ',' + row }
}
function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const k = c - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}
const addrName = (a) => colName(a.col) + a.row

// ---- tokenizer / parser ----
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
      if (i < s.length && /[A-Za-z0-9_.]/.test(s[i])) return null
      continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw new Error('parse') }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { n: 'paren', x: e }
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { n: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word') fail()
        p++
        return { n: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', a: parseAddr(t.v) }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

function misplaced(e, direct = false) {
  switch (e.n) {
    case 'range': return !direct
    case 'bin': return misplaced(e.l) || misplaced(e.r)
    case 'un': return misplaced(e.x)
    case 'paren': return misplaced(e.x)
    case 'call': return e.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: c, row: r, key: c + ',' + r })
  return out
}

function collectDeps(e, set) {
  switch (e.n) {
    case 'ref': if (e.a) set.set(e.a.key, e.a); break
    case 'range':
      if (e.a && e.b) for (const c of rangeCells(e.a, e.b)) set.set(c.key, c)
      break
    case 'bin': collectDeps(e.l, set); collectDeps(e.r, set); break
    case 'un': case 'paren': collectDeps(e.x, set); break
    case 'call': e.args.forEach((a) => collectDeps(a, set)); break
  }
}

// ---- read sheet ----
const input = fs.readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const word = m[0]
  let rest = s.slice(word.length).replace(/^[ \t]+/, '')
  const a = parseAddr(word)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${word}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addrName(a)} is declared twice\n`)
    process.exit(2)
  }
  const cell = { a, content: rest }
  if (rest[0] === '=') {
    const ast = parseFormula(rest.slice(1))
    cell.ast = ast && !misplaced(ast) ? ast : null
    cell.parsed = ast
  }
  cells.set(a.key, cell)
}

const sorted = [...cells.values()].sort((x, y) => x.a.col - y.a.col || x.a.row - y.a.row)

// ---- evaluation ----
const memo = new Map()
const active = new Set()

function evalCell(a) {
  const cell = cells.get(a.key)
  if (!cell) return num(0)
  if (memo.has(a.key)) return memo.get(a.key)
  if (active.has(a.key)) return err('#CYCLE!')
  active.add(a.key)
  let v
  const c = cell.content
  if (c[0] === '=') {
    v = cell.ast ? evaluate(cell.ast) : err('#ERR!')
  } else if (c === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = num(Number(c))
  else if (ERRORS.includes(c)) v = err(c)
  else v = text(c)
  active.delete(a.key)
  memo.set(a.key, v)
  return v
}

function toNum(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function rank(v) { return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2 }
function compare(l, r) {
  const a = rank(l), b = rank(r)
  if (a !== b) return a < b ? -1 : 1
  if (l.t === 'bool') return Number(l.v) - Number(r.v)
  if (l.t === 'num') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
}

// expand argument into list of values
function argValues(e) {
  if (e.n === 'range') {
    if (!e.a || !e.b) return [err('#REF!')]
    return rangeCells(e.a, e.b).map(evalCell)
  }
  return [evaluate(e)]
}

function scalarArg(e) {
  const vs = argValues(e)
  const bad = vs.find((v) => v.t === 'err')
  if (bad) return bad
  if (vs.length !== 1) return err('#VALUE!')
  return vs[0]
}

function evaluate(e) {
  switch (e.n) {
    case 'num': return num(e.v)
    case 'bool': return bool(e.v)
    case 'paren': return evaluate(e.x)
    case 'ref': return e.a ? evalCell(e.a) : err('#REF!')
    case 'un': {
      const x = toNum(evaluate(e.x))
      if (x.t === 'err') return x
      return num(e.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = evaluate(e.l)
      const r = evaluate(e.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(e.op)) {
        if (l.t === 'err') return l
        if (r.t === 'err') return r
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[e.op]
        return bool(res)
      }
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(r)
      if (b.t === 'err') return b
      switch (e.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return callFn(e)
  }
  return err('#ERR!')
}

function callFn(e) {
  const { name, args } = e
  const n = args.length
  if (name === 'IF') {
    if (n !== 3) return err('#ERR!')
    const c = scalarArg(args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.v
    else if (c.t === 'num') truth = c.v !== 0
    else return err('#VALUE!')
    return scalarArg(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (n !== 1) return err('#ERR!')
    const v = toNum(scalarArg(args[0]))
    if (v.t === 'err') return v
    return num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (n < 1) return err('#ERR!')
  const vals = args.flatMap(argValues)
  const bad = vals.find((v) => v.t === 'err')
  if (bad) return bad
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return finite(Math.min(...nums))
    case 'MAX': return finite(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

// ---- output ----
function show(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const cell of sorted) {
  const name = addrName(cell.a)
  if (mode[0] === 'values') {
    out += `${name}=${show(evalCell(cell.a))}\n`
  } else {
    const set = new Map()
    if (cell.parsed) collectDeps(cell.parsed, set)
    const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${name}:${list.map((a) => ' ' + addrName(a)).join('')}\n`
  }
}
process.stdout.write(out)
"}

