      while (i < n && s[i] !== '\n') advance()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      advanceN(2)
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { advanceN(2); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { advanceN(2); depth-- }
