export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

export class Table { constructor() { this.map = new Map(); this.flag = false } }
export class Aot { constructor() { this.items = [] } }
export class Scalar { constructor(t, v) { this.t = t; this.v = v } }
export class Arr { constructor() { this.items = [] } }

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  get c() { return this.s[this.i] }
  // end of meaningful content
  atEnd() { const c = this.c; return c === undefined || c === '#' || c === ';' }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(m, e)) { out += m[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6; continue
        }
        fail('invalid escape \\' + e)
      }
      out += c; this.i++
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, j); this.i = j + 1; return r
  }
  name() {
    const c = this.c
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.c)) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') { this.i++; this.ws(); parts.push(this.name()) } else { this.i = save; return parts }
    }
  }

  value(base, inArray) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';') fail(inArray ? 'unterminated array' : 'expected a value')
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return new Scalar('string', this.basic())
    if (c === "'") return new Scalar('string', this.literal())
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return new Scalar('boolean', true)
    if (tok === 'false') return new Scalar('boolean', false)
    const int = '\\d+(_\\d+)*'
    if (new RegExp(`^[+-]?${int}$`).test(tok)) return new Scalar('integer', Number(tok.replace(/_/g, '')))
    if (new RegExp(`^[+-]?${int}(\\.${int})?([eE][+-]?${int})?$`).test(tok)) return new Scalar('float', Number(tok.replace(/_/g, '')))
    fail('invalid value ' + tok)
  }
  array(base) {
    this.i++
    const a = new Arr()
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return a }
      a.items.push(this.value(base, true))
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return a }
      fail('unterminated array')
    }
  }
  inline(base) {
    this.i++
    const t = new Table(); t.flag = true
    this.ws()
    if (this.c === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...base, ...parts])
      assign(t, base, parts, v)
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return t }
      fail('unterminated inline table')
    }
  }
}

function descend(t, base, parts) {
  let path = [...base]
  for (const p of parts) {
    path.push(p)
    let n = t.map.get(p)
    if (n === undefined) { n = new Table(); t.map.set(p, n) }
    if (n instanceof Aot) n = n.items[n.items.length - 1]
    if (!(n instanceof Table)) fail(path.join('.') + ' is not a table')
    t = n
  }
  return t
}

function assign(t, base, parts, v) {
  const tt = descend(t, base, parts.slice(0, -1))
  const last = parts[parts.length - 1]
  if (tt.map.has(last)) fail('key ' + [...base, ...parts].join('.') + ' is defined twice')
  tt.map.set(last, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root, curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.atEnd()) continue
      if (L.c === '[') {
        const aot = lines[n][L.i + 1] === '['
        L.i += aot ? 2 : 1
        L.ws()
        const parts = L.dotted()
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (aot) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = descend(root, [], parts.slice(0, -1))
        const last = parts[parts.length - 1]
        const pp = parts.slice(0, -1)
        const full = parts.join('.')
        const ex = parent.map.get(last)
        void pp
        if (aot) {
          let a = ex
          if (ex === undefined) { a = new Aot(); parent.map.set(last, a) }
          else if (!(ex instanceof Aot)) fail(full + ' is not an array of tables')
          const t = new Table(); t.flag = true
          a.items.push(t); cur = t
        } else {
          if (ex === undefined) { const t = new Table(); t.flag = true; parent.map.set(last, t); cur = t }
          else if (!(ex instanceof Table)) fail(full + ' is not a table')
          else if (ex.flag) fail('table ' + full + ' is defined twice')
          else { ex.flag = true; cur = ex }
        }
        curPath = parts
        continue
      }
      const parts = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value([...curPath, ...parts])
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, parts, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
